(91, '2016-10-22', 'Loyalty Plus', 'Mr', 'Bonakurthi', 'Suman', 'managing director', 'MP', 'Visit', 'Promoting', 'Individuals', 'Worldwide', '- Gioi thieu hinh anh HTBB & PLCD\r\n- Loyalty Plus hình thuc bán thẻ hàng năm phi thường niên 180USD.\r\n- Khách có thể booking vé máy bay, tour và dat phòng. Là partner cua Lan Rừng mỗi tuần khách book khoảng 30 room night.\r\n- Xin cuoc hen với Ms. Trúc de trao doi hop tác', 'gui giá 2016-2017', NULL, 'Yes', '2016-10-22 09:18:23', '2016-10-22 09:18:23', 26, 26, 'Ho Tram Beach Boutique,Poulo Condor', 'FIT', '', '0915193536', '0000-00-00', '2016-10-20', '0000-00-00', 'Lau 6, Nguyen Lam Tower, 133 Duong Ba Trac, Quan 8', 'sumanb@loyaltyplus.com.vn', '', 0, 'Ho Chi Minh', 'Vietnam'),
(92, '2016-10-22', 'Vien Dao Tao Quoc Te - Dai Hoc Tp.HCM', 'Ms', 'Le', 'My Linh', 'Admin', 'MP', 'Tele', 'Promoting', 'Groups', 'local', '- Gioi thieu hình anh HTBB\r\n- Khách thường tổ chức tổng kết về khóa học.\r\n- Thường vào tháng 10-11 hàng năm\r\n- Quan tham ve giá phòng \r\n- sẽ liên hệ khi có sự kiện', 'gui gia promotion tháng 10/2016', NULL, 'Yes', '2016-10-22 09:33:44', '2016-10-22 09:33:44', 26, 26, 'Ho Tram Beach Boutique', 'GIT', '', '0902751177', '0000-00-00', '2016-10-05', '0000-00-00', '17 Phạm Ngọc Thạch, Phường 6, Quận 3 , Tp. Hồ Chí Minh', 'linh.le@isb.edu.vn', '', 0, 'Ho Chi Minh', 'Vietnam'),
