(95, '2016-10-22', 'Global Holiday Travel', 'Mr', 'Le', 'Quang Phi Hung', 'Sales Manager', 'MP', 'Visit', 'Qualifying', 'Groups', 'local', '- Gioi thie hinh anh HTBB- PLCD\r\n- thường gui booking FIT cho HTBB\r\n- Hè này có book đoàn đến Hồ Tràm nhưng chọn Vietso Pertro vì giá tương đối thấp.\r\n- Hồ Tràm Beach so với mặt bằng chung hơi cao phòng ốc cũ so với các resort lân cận\r\n- mong được giá tốt khi có đoàn', 'báo giá 2016-2017 giá promotion tháng 10-2016', NULL, 'Yes', '2016-10-22 10:21:46', '2016-10-22 10:21:46', 26, 26, 'Ho Tram Beach Boutique,Poulo Condor', 'GIT', '', '0988183809', '0000-00-00', '2016-10-19', '0000-00-00', '21 Phan Kế Bính, phường Đa Kao, Quận 1', 'hung.le@globalholidays.com.vn', '', 0, 'Ho Chi Minh', 'Vietnam');
